-- Demo neighbors, listings and conversations.




-- Inserted oldest first so the trigger leaves each conversation's newest message on it.

-- Both sides have read everything except the threads left unread on purpose.
update conversations set buyerReadAt = lastMessageAt, sellerReadAt = lastMessageAt;
update conversations set sellerReadAt = lastMessageAt - interval '1 minute' where id = '806f056a-23e8-527d-8e9b-09a545a99926';
update conversations set sellerReadAt = lastMessageAt - interval '1 minute' where id = 'f5e3cf5d-b336-5397-afc8-4a7ed3320b28';
update conversations set buyerReadAt = lastMessageAt - interval '1 minute' where id = '03d272df-7fd2-5f8c-bde2-c1a1cc98af78';


