insert into listings (id, createdAt, sellerId, sellerName, neighborhoodId, title, price, category, condition, description, status) values
  ('060fc205-f492-5306-99d2-76fe2d5a4ddf', now() - interval '5 hours', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', (select id from neighborhoods where name = 'Maple Hill'), 'Leather recliner', 240, 'furniture', 'good', 'Oversized recliner in brown leather. Reclines smoothly with the side lever, very comfortable, a few scuffs on the base. You''ll need a car, it''s heavy.', 'available'),
  ('9f211792-8728-5c8d-aa35-050d274ab5bf', now() - interval '30 hours', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', (select id from neighborhoods where name = 'Maple Hill'), 'Pine dining table with four chairs', 150, 'furniture', 'good', 'Solid pine table, 150 x 90 cm, with four matching chairs. Some wear on the top that sands out easily. Moving and it won''t fit the new place.', 'available'),
  ('5457a4d1-dd86-5b0f-aa34-7506ecf46f34', now() - interval '52 hours', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', (select id from neighborhoods where name = 'Maple Hill'), 'Black cube bookcase', 45, 'furniture', 'like-new', 'Wall-width bookcase with square cubbies, in black. Holds records and fabric bins nicely. Disassembled for pickup unless you want to carry it whole.', 'available'),
  ('15718258-ae32-5c52-9726-ac5925a27e98', now() - interval '20 hours', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', (select id from neighborhoods where name = 'Maple Hill'), 'Blue road bike, 56 cm', 180, 'sports', 'good', 'Dark blue road bike with a 56 cm frame, fits roughly 5''9" to 6''0". New tires and bar tape this spring. Shifts clean.', 'pending'),
  ('f7a05d8f-e8e5-5657-b812-dfb78ed6de77', now() - interval '26 hours', 'c96186fe-3d95-585e-8af8-361923a3ecc1', 'June Park', (select id from neighborhoods where name = 'Maple Hill'), 'Kids'' tricycle', 25, 'kids', 'good', 'Red metal tricycle with a bell. My son rode it everywhere until he moved up to a bike. Ages 2 to 4.', 'available'),
  ('75eed00f-df40-5748-b336-a4a1797aeeb9', now() - interval '76 hours', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', (select id from neighborhoods where name = 'Maple Hill'), 'Umbrella strollers, three of them', 60, 'kids', 'good', 'Three lightweight umbrella strollers from three kids. They fold small and fit in any trunk. $60 for all three, or $25 each.', 'available'),
  ('5709784b-b937-5ec6-ac85-e54d77f60bbb', now() - interval '19 hours', 'c96186fe-3d95-585e-8af8-361923a3ecc1', 'June Park', (select id from neighborhoods where name = 'Maple Hill'), 'Box of picture books', 0, 'books', 'good', 'About 25 picture books, board books and early readers. Free to a good home. Box is on my porch at the corner of Elm and 4th.', 'available'),
  ('ba3dbbe9-f321-569c-95d3-52753fa5ea1c', now() - interval '120 hours', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', (select id from neighborhoods where name = 'Maple Hill'), '12" cast iron skillet', 20, 'home', 'like-new', 'Pre-seasoned 12 inch cast iron skillet. Used a handful of times. I have too many pans.', 'sold'),
  ('d39b9e13-3800-5a4c-8ee9-4c38c5047604', now() - interval '2 hours', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', (select id from neighborhoods where name = 'Maple Hill'), 'Tomato seedlings, tray of 12', 0, 'home', 'new', 'Started too many tomatoes again. Sungold and Brandywine, about 15 cm tall and ready to plant out. Take a few or all of them.', 'available'),
  ('9656943b-bc90-562d-9000-24f5fed85e7f', now() - interval '44 hours', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', (select id from neighborhoods where name = 'Maple Hill'), 'Cordless drill with two batteries', 45, 'tools', 'good', '18V cordless drill/driver, two batteries and charger. Holds a charge fine. Bits not included.', 'available'),
  ('dfce5068-fe71-5fea-a60f-62da89488849', now() - interval '60 hours', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', (select id from neighborhoods where name = 'Maple Hill'), 'Acoustic guitar with gig bag', 120, 'books', 'good', 'Dreadnought acoustic, solid spruce top. Plays well, strings changed last month. Includes padded gig bag and a capo.', 'available'),
  ('70c6502d-b2b0-590e-80d2-6fea40a17410', now() - interval '26 hours', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', (select id from neighborhoods where name = 'Maple Hill'), 'Vintage turntable', 90, 'electronics', 'good', 'Belt-drive turntable, recently serviced with a new belt and stylus. Sounds great. Needs an amp or powered speakers.', 'available'),
  ('410997aa-36d5-5ca5-8d0e-b5d24f005ac9', now() - interval '14 hours', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', (select id from neighborhoods where name = 'Maple Hill'), 'Monstera plant in pot', 15, 'home', 'good', 'Healthy monstera, about 80 cm tall, in a white ceramic pot. It has outgrown my window.', 'available'),
  ('51867062-f0b3-5353-9d56-61d0c1c6e3e6', now() - interval '90 hours', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', (select id from neighborhoods where name = 'Maple Hill'), '4-person camping tent', 70, 'sports', 'good', 'Dome tent, sleeps four. Used on three trips, no tears, all poles and stakes included. Rainfly too.', 'available'),
  ('c83b3d78-d68f-5112-a961-8803e9e10ad4', now() - interval '36 hours', 'c96186fe-3d95-585e-8af8-361923a3ecc1', 'June Park', (select id from neighborhoods where name = 'Maple Hill'), 'Men''s wool winter coat, size M', 35, 'clothing', 'like-new', 'Navy wool-blend overcoat, men''s medium. Worn maybe five times. Dry cleaned.', 'available'),
  ('a17d6ba1-00fa-5ff8-8cc9-15aedb2251ac', now() - interval '11 hours', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', (select id from neighborhoods where name = 'Maple Hill'), 'Retro mechanical keyboard', 50, 'electronics', 'like-new', 'Mechanical keyboard with round typewriter-style keycaps. Tactile switches, USB-C. Clacky in the best way.', 'available'),
  ('66ad80b1-c368-59bb-9f97-b57846b272f7', now() - interval '1 hours', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', (select id from neighborhoods where name = 'Maple Hill'), 'Moving boxes, about 20', 0, 'home', 'good', 'Just finished unpacking. About 20 boxes, mixed sizes, plus a roll of packing paper. Free, please take them all.', 'available'),
  ('b707f365-1450-57b1-917f-c155b41720f0', now() - interval '100 hours', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', (select id from neighborhoods where name = 'Maple Hill'), 'Snowboard, 156 cm', 110, 'sports', 'good', 'Wood-core all-mountain board, 156 cm. Base waxed at the end of last season. Bindings not included.', 'available'),
  ('6ee47a18-6d62-51b0-a7ea-f8af9532c51c', now() - interval '18 hours', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', (select id from neighborhoods where name = 'Maple Hill'), 'Push reel lawn mower', 55, 'tools', 'good', 'Quiet, no gas, no cord. Blades sharpened in April. Great for a small yard.', 'available'),
  ('2db8dd3b-c5b3-57a7-b764-93e4eb78724e', now() - interval '48 hours', 'c96186fe-3d95-585e-8af8-361923a3ecc1', 'June Park', (select id from neighborhoods where name = 'Maple Hill'), 'Board game night bundle', 30, 'books', 'good', 'A stack of family games, all pieces checked and complete. Take the lot.', 'available'),
  ('67c05e76-7aa3-55b6-b4e6-81db78dffdce', now() - interval '22 hours', 'a7f5909b-2781-58e2-8f29-36384bf494c2', 'Sam Whitfield', (select id from neighborhoods where name = 'Riverside'), 'Black leather sofa', 300, 'furniture', 'good', 'Three-seat tufted leather sofa in black. Comfortable and sturdy, some patina on the arms. From a smoke-free, pet-free home.', 'available'),
  ('83b26fe8-8edd-5e14-99c2-fc32a636530d', now() - interval '6 hours', '456c70bb-6248-51b2-a90c-79d5b7fc9251', 'Priya Nair', (select id from neighborhoods where name = 'Riverside'), 'Shelf of paperbacks', 0, 'books', 'fair', 'Mystery, sci-fi and a few literary novels, around 40 in all. Free, just bring a bag.', 'available'),
  ('fffb32d7-14b4-5d80-8256-1968aa5d0a78', now() - interval '28 hours', 'eb837d66-1d73-5326-97f9-35256c9b4f60', 'Leo Moretti', (select id from neighborhoods where name = 'Riverside'), 'Drawing tablet with pen', 150, 'electronics', 'good', 'Pen tablet for drawing and photo editing. Plugs into any laptop over USB. Pen and spare nibs included.', 'pending'),
  ('a5ad69ab-52a5-5060-9be4-c3287f14b2ad', now() - interval '70 hours', '456c70bb-6248-51b2-a90c-79d5b7fc9251', 'Priya Nair', (select id from neighborhoods where name = 'Riverside'), 'White crib', 80, 'kids', 'good', 'Convertible crib in white. Mattress not included. Hardware bagged and labeled.', 'available'),
  ('8d641f7b-a5c5-5ea2-a473-3d99afef6d7e', now() - interval '40 hours', 'a7f5909b-2781-58e2-8f29-36384bf494c2', 'Sam Whitfield', (select id from neighborhoods where name = 'Riverside'), 'Garden wheelbarrow', 30, 'tools', 'fair', 'Steel wheelbarrow, some rust but solid. Tire holds air.', 'available'),
  ('1b581f30-99db-588a-a742-9369de7527eb', now() - interval '9 hours', 'eb837d66-1d73-5326-97f9-35256c9b4f60', 'Leo Moretti', (select id from neighborhoods where name = 'Riverside'), 'Yoga mat', 12, 'sports', 'like-new', 'Thick 6 mm mat, barely used. Comes with a carry strap.', 'available'),
  ('8f01e418-b1f4-50ab-8f39-e34bd25f5ebc', now() - interval '4 hours', '456c70bb-6248-51b2-a90c-79d5b7fc9251', 'Priya Nair', (select id from neighborhoods where name = 'Riverside'), 'Pink rain boots', 0, 'clothing', 'good', 'Pink rubber rain boots, kids'' size 11. Free.', 'available'),
  ('c802b07d-cfc6-5774-9c02-8fe5f9119173', now() - interval '150 hours', 'a7f5909b-2781-58e2-8f29-36384bf494c2', 'Sam Whitfield', (select id from neighborhoods where name = 'Riverside'), 'Espresso machine', 95, 'home', 'good', 'Semi-automatic espresso machine with steam wand. Descaled monthly. Upgraded, so this one needs a new home.', 'sold'),
  ('76a5b0c2-9394-518c-a454-aaf157f46263', now() - interval '12 hours', 'eb837d66-1d73-5326-97f9-35256c9b4f60', 'Leo Moretti', (select id from neighborhoods where name = 'Riverside'), 'Adjustable desk lamp', 12, 'furniture', 'good', 'Metal desk lamp with an adjustable arm. Takes a standard bulb.', 'available'),
  ('bc09fee5-74e0-5c78-b919-22f46959929e', now() - interval '16 hours', '456c70bb-6248-51b2-a90c-79d5b7fc9251', 'Priya Nair', (select id from neighborhoods where name = 'Riverside'), 'Denim jacket, unisex L', 25, 'clothing', 'good', 'Well-worn in the good way. Unisex large.', 'available');
