insert into messages (createdAt, conversationId, senderId, senderName, body) values
  (now() - interval '1500 minutes', 'ea089069-3229-5485-8e4c-93108b8b1175', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', 'Do the chairs have cushions?'),
  (now() - interval '1440 minutes', 'ea089069-3229-5485-8e4c-93108b8b1175', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', 'No cushions, solid wood seats.'),
  (now() - interval '900 minutes', '47e407e3-210d-5814-953f-fa19eabeb547', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', 'Hey, is the bike still for sale? What''s the standover height?'),
  (now() - interval '880 minutes', '47e407e3-210d-5814-953f-fa19eabeb547', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', 'About 80 cm. Want to test ride it this evening?'),
  (now() - interval '860 minutes', '47e407e3-210d-5814-953f-fa19eabeb547', '6aa68628-0940-503c-b69e-3941df638d4b', 'Rosa Jiménez', 'Yes please, I''ll come by around 6.'),
  (now() - interval '600 minutes', 'e81f79a5-db87-5fc8-bc55-951167fb2886', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', 'Hi Theo, does the turntable have a built-in preamp?'),
  (now() - interval '560 minutes', 'e81f79a5-db87-5fc8-bc55-951167fb2886', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', 'It doesn''t, but I have an old phono preamp I can throw in for $10.'),
  (now() - interval '540 minutes', 'e81f79a5-db87-5fc8-bc55-951167fb2886', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', 'Deal. Can I come by Saturday morning?'),
  (now() - interval '520 minutes', 'e81f79a5-db87-5fc8-bc55-951167fb2886', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', 'Saturday works. Anytime after 9.'),
  (now() - interval '300 minutes', '47e407e3-210d-5814-953f-fa19eabeb547', '60f0cb0e-c3f3-5c0b-9910-e0c5aa202d0d', 'Theo Lindqvist', 'Marked it pending for you. See you tonight!'),
  (now() - interval '240 minutes', '806f056a-23e8-527d-8e9b-09a545a99926', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', 'Hi Maya! Is the recliner still available?'),
  (now() - interval '230 minutes', '806f056a-23e8-527d-8e9b-09a545a99926', '9e1463cd-4b72-5460-95cb-a86cae604cd9', 'Maya Patel', 'It is! Happy to hold it for you if you want to see it.'),
  (now() - interval '200 minutes', '806f056a-23e8-527d-8e9b-09a545a99926', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', 'Great. Would you take $200? I can pick it up tomorrow with my van.'),
  (now() - interval '180 minutes', '03d272df-7fd2-5f8c-bde2-c1a1cc98af78', '456c70bb-6248-51b2-a90c-79d5b7fc9251', 'Priya Nair', 'Love the sofa. Would you deliver? I''m just across the river walk.'),
  (now() - interval '150 minutes', '03d272df-7fd2-5f8c-bde2-c1a1cc98af78', 'a7f5909b-2781-58e2-8f29-36384bf494c2', 'Sam Whitfield', 'I can help carry it if you bring a truck. It''s only a few blocks.'),
  (now() - interval '40 minutes', 'f5e3cf5d-b336-5397-afc8-4a7ed3320b28', 'c96186fe-3d95-585e-8af8-361923a3ecc1', 'June Park', 'Could I grab four of the Sungolds? I''m two doors down.'),
  (now() - interval '12 minutes', '806f056a-23e8-527d-8e9b-09a545a99926', '1cb7abe0-3bad-527d-930f-342ea2d24584', 'Ben Okafor', 'Also, does the back lift off for moving?');
